descriptor.controllerScript:
self.onInit = function () {
    var root = self.ctx.$container[0];
    var $ = function (s) { return root.querySelector(s); };
    var http = self.ctx.http;
    var elTotal = $('.lq-total');
    var elUsed = $('.lq-used');
    var elLeft = $('.lq-left');
    var input = $('.lq-add');
    var btn = $('.lq-btn');
    var msg = $('.lq-msg');
    var usedValue = 0;
    var usedDs = null;
    var lastTotal = 0;

    function num(v) { var n = parseFloat(v); return isNaN(n) ? 0 : n; }
    function last(s) { var d = s.data; return (d && d.length) ? d[d.length - 1][1] : undefined; }
    function fmt(v) { return v.toFixed(1) + ' L'; }

    function show(text, ok) {
        msg.textContent = text;
        msg.style.color = ok ? '#1b5e20' : '#b71c1c';
    }

    function errText(e) {
        return (e && e.error && e.error.message) ? e.error.message : 'Ismeretlen hiba';
    }

    function render() {
        elTotal.textContent = fmt(lastTotal);
        elUsed.textContent = fmt(usedValue);
        var left = lastTotal - usedValue;
        elLeft.textContent = fmt(left);
        elLeft.style.color = left < 0 ? '#b71c1c' : '';
    }

    // total = sum of total_l over all machines, used = attribute used_l of the usage asset
    function update() {
        var total = 0;
        var dbg = [];
        (self.ctx.data || []).forEach(function (s) {
            var name = s.dataKey.name;
            var label = s.dataKey.label;
            var v = last(s);
            dbg.push(name + '=' + v);
            if ((name === 'total_l' || label === 'total_l') && v !== undefined) { total += num(v); }
            if (name === 'used_l' || label === 'used_l') {
                usedDs = s.datasource;
                if (v !== undefined) { usedValue = num(v); }
            }
        });
        lastTotal = total;
        render();
        var d = root.querySelector('.lq-dbg');
        if (d) { d.textContent = dbg.join(' | '); }
    }

    btn.addEventListener('click', function () {
        var add = parseFloat(String(input.value).replace(',', '.'));
        if (isNaN(add) || add === 0) { show('Adj meg egy számot (a negatív szám javít).', false); return; }
        if (!usedDs || !usedDs.entityId) { show('Nincs "used_l" adatforrás a widgetben.', false); return; }

        var next = Math.max(0, Math.round((usedValue + add) * 100) / 100);
        btn.disabled = true;
        http.post('/api/plugins/telemetry/' + usedDs.entityType + '/' + usedDs.entityId + '/attributes/SERVER_SCOPE',
                  { used_l: next }).subscribe(
            function () {
                usedValue = next;
                render();
                input.value = '';
                show('Mentve.', true);
                btn.disabled = false;
            },
            function (e) { show('Hiba: ' + errText(e), false); btn.disabled = false; }
        );
    });

    self.onDataUpdated = update;
    update();
};

self.onDestroy = function () {};

